using System;using System.IO;using System.Collections.Generic;using System.Web.Script.Serialization;using BongoChat.Protocol;using BongoCat;using BongoCat.Multiplayer;using UnityEngine;using Heathen.SteamworksIntegration;
namespace BongoChatBridge{public sealed partial class BridgePlugin{public void InitOthers(){InitializeOtherChests();}public void TickBoth(float time){UpdateAutoChests(time);UpdateOtherChests(time);}public bool OtherSupported{get{return autoOtherChestSupported;}}public string OtherStatus{get{return autoOtherChestStatus;}}}}
public static class BridgeOtherChestTests
{
 static int checks;static float tick;static string folder,owner=Guid.NewGuid().ToString("N");static JavaScriptSerializer json=new JavaScriptSerializer();static BongoChatBridge.BridgePlugin bridge;
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
 static void Tick(){tick+=3;bridge.TickBoth(tick);}
 static void Lease(bool on=true,string room="123",string session="test-session",int age=0,string kind="other_chests"){var now=DateTime.UtcNow.AddSeconds(-age);File.WriteAllText(Path.Combine(folder,"other-chests.json"),json.Serialize(new AutoChestLease{protocol=1,kind=kind,owner=owner,session=session,room=room,enabled=on,createdUtc=now.ToString("o"),expiresUtc=now.AddSeconds(5).ToString("o")}));}
 static OpenChestForMember Box(ulong id,bool emote=false){var user=new UserData{SteamId=id};var data=new LobbyMemberData{lobby=LobbyData.Current,user=user,Values=new Dictionary<string,string>{{"chest_ready","true"},{"emote_chest_ready","true"}}};var members=new List<LobbyMemberData>(LobbyData.Current.Members??new LobbyMemberData[0]);members.RemoveAll(x=>x.user.SteamId==id);members.Add(data);LobbyData.Current.Members=members.ToArray();return new OpenChestForMember{_targetUser=new SteamUserData{Data=user},_chestType=emote?ChestType.Emote:ChestType.Normal,_setChestActive=new SetActiveBasedOnLobbyMemberValue{_key=emote?"emote_chest_ready":"chest_ready",_lobbyMemberData=new SteamLobbyMemberData{Data=data}}};}
 static void Ready(OpenChestForMember box,bool ready){box._setChestActive._lobbyMemberData.Data.Values[box._chestType==ChestType.Emote?"emote_chest_ready":"chest_ready"]=ready?"true":"false";}
 static void ClearBusy(){Shop.NormalShop._pendingGiftPayoffs.Clear();Shop.EmoteShop._pendingGiftPayoffs.Clear();Steam.ChestExchanger.IsExchanging=false;}
 public static int Main(string[] args){try{
  folder=Path.GetFullPath(args[0]);Directory.CreateDirectory(folder);Shop.NormalShop=new Shop(false){ChestIsReady=false};Shop.EmoteShop=new Shop(true){ChestIsReady=false};LobbyData.Current=new LobbyData{SteamId=new Steamworks.CSteamID{m_SteamID=123},Members=new LobbyMemberData[0]};bridge=new BongoChatBridge.BridgePlugin(folder);bridge.InitOthers();var first=Box(10);Resources.Items=new UnityEngine.Object[]{first};
  Check(bridge.OtherSupported,"actual other-member adapter binds the installed API shape");Tick();Check(first.Calls==0,"without separate permission no other chest is opened");Lease(kind:"auto_chests");Tick();Check(first.Calls==0,"own-chest permission cannot enable other-member opening");Lease(room:"456");Tick();Lease(session:"stale");Tick();Lease(age:10);Tick();Check(first.Calls==0,"wrong room wrong session and expired requests cannot spend points");
  Lease();first.gameObject.scene.valid=false;Tick();Check(first.Calls==0,"prefab or non-scene objects cannot receive automatic clicks");first.gameObject.scene.valid=true;first.enabled=false;Tick();first.enabled=true;first._setChestActive._gameObject.activeInHierarchy=false;Tick();Check(first.Calls==0,"disabled or hidden chest controls are never clicked");first._setChestActive._gameObject.activeInHierarchy=true;
  var self=first._targetUser.Data;self.Self=true;first._targetUser.Data=self;Tick();Check(first.Calls==0,"my own cat cannot be selected as another member");self.Self=false;first._targetUser.Data=self;
  var original=LobbyData.Current.Members;LobbyData.Current.Members=new LobbyMemberData[0];Tick();Check(first.Calls==0,"departed members cannot be selected from stale scene objects");LobbyData.Current.Members=original;
  first._setChestActive._key="other_key";Tick();Check(first.Calls==0,"unexpected native readiness keys fail closed");first._setChestActive._key="chest_ready";
  var binding=first._setChestActive._lobbyMemberData.Data;var bad=binding;bad.user=new UserData{SteamId=11};first._setChestActive._lobbyMemberData.Data=bad;Tick();Check(first.Calls==0,"mismatched target and lobby binding cannot be gifted");first._setChestActive._lobbyMemberData.Data=binding;
  first._hasClicked=true;Tick();first._hasClicked=false;first._setChestActive._frozen=true;Tick();Check(first.Calls==0,"native already-clicked and frozen states are respected");first._setChestActive._frozen=false;Ready(first,false);Tick();Check(first.Calls==0,"a not-ready member chest cannot be clicked");Ready(first,true);
  Shop.NormalShop.Points=0;Tick();Check(first.Calls==0,"insufficient local game points prevent opening for another member");Shop.NormalShop.Points=100;Tick();Check(first.Calls==1&&Shop.NormalShop.Points==99&&Shop.NormalShop.Calls==0,"native member click spends my points for another member while own automation stays off");
  var second=Box(11,true);Resources.Items=new UnityEngine.Object[]{first,second};Lease();Tick();Check(second.Calls==0,"pending native gift animation serializes subsequent gifts");ClearBusy();Ready(first,false);Tick();Check(second.Calls==1&&Shop.EmoteShop.Points==99,"ready emote chest is gifted after the normal operation finishes");ClearBusy();Ready(second,false);
  var uncertain=Box(12);uncertain.Uncertain=true;Resources.Items=new UnityEngine.Object[]{uncertain};Steam.ChestExchanger.IsExchanging=true;Tick();Check(uncertain.Calls==0,"a native Steam exchange blocks gifts");Steam.ChestExchanger.IsExchanging=false;Tick();Check(uncertain.Calls==1,"one uncertain native gift request is initiated");int gifts=Shop.NormalShop.Gifts;
  Resources.Items=new UnityEngine.Object[0];Tick();Resources.Items=new UnityEngine.Object[]{uncertain};Tick();Check(uncertain.Calls==1&&Shop.NormalShop.Gifts==gifts,"UI hiding cannot rearm an uncertain gift");
  var replacement=new OpenChestForMember{_targetUser=uncertain._targetUser,_setChestActive=uncertain._setChestActive,Uncertain=true};Resources.Items=new UnityEngine.Object[]{replacement};Tick();Check(replacement.Calls==0,"recreated controls cannot duplicate the same member readiness cycle");Ready(replacement,false);Tick();Ready(replacement,true);Tick();Check(replacement.Calls==1,"only an observed false-to-true ready cycle permits another gift");
  Lease(false);Ready(replacement,false);Tick();Ready(replacement,true);Tick();Check(replacement.Calls==1,"independent off permission stops other-member gifts");Lease();Tick();Check(replacement.Calls==2,"explicit re-enable can retry an uncertain gift");
  LobbyData.Current=new LobbyData{SteamId=new Steamworks.CSteamID{m_SteamID=456},Members=LobbyData.Current.Members};var third=Box(13);Resources.Items=new UnityEngine.Object[]{third};Tick();Check(third.Calls==0,"room switch invalidates a still-fresh old-room lease");Lease(room:"456");Tick();Check(third.Calls==1,"new-room permission permits only a verified current-room member");ClearBusy();Ready(third,false);
  var throwing=Box(14);throwing.Throw=true;Resources.Items=new UnityEngine.Object[]{throwing};Tick();Check(throwing.Calls==1&&bridge.OtherStatus=="error","native click exception is isolated from chat");tick+=6;Lease(room:"456");Tick();Check(throwing.Calls==1,"exception after a possible point deduction is not retried automatically");
  File.WriteAllText(Path.Combine(folder,"other-chests.json"),new string('x',5000));Tick();Check(throwing.Calls==1,"oversized permission does not spend additional points");
  ClearBusy();var both=Box(15);Resources.Items=new UnityEngine.Object[]{both};Lease(room:"456");Shop.NormalShop.ChestIsReady=true;var now=DateTime.UtcNow;File.WriteAllText(Path.Combine(folder,"auto-chests.json"),json.Serialize(new AutoChestLease{protocol=1,kind="auto_chests",owner=owner,session="test-session",enabled=true,createdUtc=now.ToString("o"),expiresUtc=now.AddSeconds(5).ToString("o")}));Tick();Check(Shop.NormalShop.Calls==1&&both.Calls==0,"own and other automatic clicks share one serialized action window");Tick();Check(both.Calls==0,"an in-progress own opening also blocks other-member gifts");
  Console.WriteLine("All "+checks+" bridge other-member checks passed.");return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}